layer.css:
[data-ryt="footer"] { background-color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none; color: var(--ryt-bg) }
[data-ryt="section"] > h2 { color: rgb(51, 51, 51); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.1; letter-spacing: 2.4px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(51, 51, 51); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: #3b9fb1; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: 1.429; letter-spacing: 0.96px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(56, 167, 187); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.2s ease-out }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="nav"] a { color: var(--ryt-text); border-top: 5px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 700; font-style: normal; line-height: 1.429; letter-spacing: 1.12px; text-transform: uppercase; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 21px; padding-right: 15px; padding-bottom: 21px; padding-left: 15px; transition: 0.2s ease-out; border-right: none; border-bottom: none; border-left: none }
[data-ryt="button"] { color: rgb(56, 167, 187); background-color: var(--ryt-bg); border-top: 2px outset rgb(56, 167, 187); border-right: 2px outset rgb(56, 167, 187); border-bottom: 2px outset rgb(56, 167, 187); border-left: 2px outset rgb(56, 167, 187); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.429; letter-spacing: 1.12px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(56, 167, 187); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 6px; padding-right: 12px; padding-bottom: 6px; padding-left: 12px; transition: 0.2s ease-out }
[data-ryt="review"] { color: #929292; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.429; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(153, 153, 153); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: #3b9fb1; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 800; font-style: normal; letter-spacing: 1.12px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(56, 167, 187); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s ease-out }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 800; font-style: normal; line-height: 1.5; letter-spacing: 1.12px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #267280; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="button"]:hover { color: #38a7bb; background-color: rgb(230, 230, 230); color: var(--ryt-bg) }
[data-ryt="nav"] a:hover { background-color: rgb(238, 238, 238); color: var(--ryt-text); background-color: #80cbd9; color: #267280; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: #267280; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
